// Shared constants for both pages. Pain data comes from wfp.js (generated by scripts/fetch_paintrack.py).
var OZ_TO_G = 28.35;
var COOKING_YIELD = 0.75;           // USDA ARS: cooked weight as a share of raw
var LIVE_LB_PER_YEAR = 61.1e9;      // USDA NASS 2024: lb of live chickens produced in the U.S.
var BIRDS_PER_YEAR = 9.33e9;        // USDA NASS 2024: chickens produced
var LIVE_LB = LIVE_LB_PER_YEAR / BIRDS_PER_YEAR;   // 6.55 lb per bird
var DRESSING = 0.75;                // University of Maine Extension: carcass as a share of live weight
var EDIBLE_SHARE = 0.74;            // University of Wisconsin Extension: boneless meat as a share of carcass

// The two production systems the Welfare Footprint Project modelled.
var SYSTEMS = {
  conventional: { label: 'Conventional (fast-growing)', liveG: LIVE_LB * 453.6, liveTag: 'NASS', lifetimeDays: 47, lifeTag: 'NCC',
                  liveNote: 'U.S. average for 2024: all live weight produced in the year divided by the number of birds.' },
  reformed:     { label: 'Higher-welfare (slower-growing)', liveG: 2500, liveTag: 'WFP', lifetimeDays: 56, lifeTag: 'WFP',
                  liveNote: 'The project’s reformed scenario: a slower-growing breed reaching 2.5 kg at 56 days, under Better Chicken Commitment conditions.' }
};
var LEVELS = ['annoying', 'hurtful', 'disabling', 'excruciating'];
var LEVEL_NAMES = { annoying: 'Annoying', hurtful: 'Hurtful', disabling: 'Disabling', excruciating: 'Excruciating' };
var LEVEL_DEFS = {
  annoying: 'unpleasant, but does not disrupt normal activity',
  hurtful: 'hard to ignore; the bird is aware of it most of the time',
  disabling: 'continuously distressing; no enjoyment is possible',
  excruciating: 'intolerable even for seconds'
};

// Everything the pages need for one serving of cooked chicken, in grams.
function servingStats(cookedG, sysKey) {
  var sys = SYSTEMS[sysKey];
  var data = WFP.systems[sysKey];
  var rawG = cookedG / COOKING_YIELD;
  var rawPerBird = sys.liveG * DRESSING * EDIBLE_SHARE;
  var lifetimes = rawG / rawPerBird;
  var causes = data.causes.map(function (c) {
    return { name: c.name, what: c.what, hours: c.total * lifetimes, lo: c.total_lo * lifetimes, hi: c.total_hi * lifetimes, perBird: c.total };
  });
  var levels = LEVELS.map(function (l) {
    var p = data.published[l];
    return { key: l, name: LEVEL_NAMES[l], def: LEVEL_DEFS[l], hours: p.mean * lifetimes, lo: p.lo * lifetimes, hi: p.hi * lifetimes, perBird: p.mean };
  });
  var allPerBird = data.causes.reduce(function (s, c) { return s + c.total; }, 0);
  return { cookedG: cookedG, rawG: rawG, rawPerBird: rawPerBird, lifetimes: lifetimes,
           days: lifetimes * sys.lifetimeDays, lifetimeDays: sys.lifetimeDays,
           causes: causes, levels: levels, allHours: allPerBird * lifetimes, allPerBird: allPerBird };
}
